function validate([receiver, k]) {
  const n = receiver.length;
  if (n < 1 || n > 100000) return 'receiver needs 1 to 10^5 players.';
  if (receiver.some(v => !Number.isInteger(v) || v < 0 || v > n - 1)) return 'Each receiver[i] is between 0 and n - 1.';
  if (!Number.isInteger(k) || k < 1 || k > 10000000000) return 'k is between 1 and 10^10.';
  return null;
}

