function getMaxFunctionValue(receiver, k) {
  const n = receiver.length;
  let jump = receiver.slice();
  let gain = receiver.slice();
  const position = Array.from({ length: n }, (_, i) => i);
  const score = position.slice();
  let remaining = k;

  while (remaining > 0) {
    if (remaining % 2 === 1) {
      for (let i = 0; i < n; i++) {
        score[i] += gain[position[i]];
        position[i] = jump[position[i]];
      }
    }
    remaining = Math.floor(remaining / 2);
    if (remaining > 0) {
      const nextJump = new Array(n);
      const nextGain = new Array(n);
      for (let x = 0; x < n; x++) {
        nextJump[x] = jump[jump[x]];
        nextGain[x] = gain[x] + gain[jump[x]];
      }
      jump = nextJump;
      gain = nextGain;
    }
  }

  let best = 0;
  for (const value of score) {
    best = Math.max(best, value);
  }
  return best;
}

