function getMaxFunctionValue(receiver, k) {
  // Walk from each start until a player repeats, then count whole laps of the cycle.
  let best = 0;
  for (let s = 0; s < receiver.length; s++) {
    const firstSeen = new Map();
    const prefix = [0];
    let x = s, t = 0;
    while (!firstSeen.has(x) && t <= k) {
      firstSeen.set(x, t);
      prefix.push(prefix[t] + x);
      x = receiver[x];
      t++;
    }
    let total;
    if (t > k) total = prefix[k + 1];
    else {
      const c0 = firstSeen.get(x), len = t - c0, lap = prefix[t] - prefix[c0];
      const left = k + 1 - c0;
      const rest = left % len;
      total = prefix[c0] + Math.floor(left / len) * lap + prefix[c0 + rest] - prefix[c0];
    }
    best = Math.max(best, total);
  }
  return best;
}

