function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 8);
  const mode = rand();
  const receiver = [];
  for (let i = 0; i < n; i++) {
    if (mode < 0.2) receiver.push(i);
    else if (mode < 0.4) receiver.push((i + 1) % n);
    else if (mode < 0.6) receiver.push(int(0, Math.min(i, n - 1)));
    else receiver.push(int(0, n - 1));
  }
  let k;
  const pick = rand();
  if (pick < 0.3) k = 10000000000 - int(0, 1000);
  else if (pick < 0.6) k = int(1, 20);
  else k = int(1, size === 'large' ? 10000000000 : 1000);
  return [receiver, k];
}
